#!/usr/bin/env bash
set -euo pipefail
state="$RUNNER_TEMP/attic-ci"
# Only remove credentials generated by this action.
rm -f "$state/netrc" "$state/mdm.xml"
rm -rf "$state/config"

if [[ -f "$state/warp-managed" ]]; then
  case "$RUNNER_OS" in
    Linux) mdm_dir=/var/lib/cloudflare-warp ;;
    macOS) mdm_dir='/Library/Application Support/Cloudflare' ;;
    *) echo "::error::Unsupported runner OS: $RUNNER_OS"; exit 1 ;;
  esac
  # Remove the enrollment token first to prevent automatic re-enrollment.
  sudo rm -f "$mdm_dir/mdm.xml"
  if command -v warp-cli > /dev/null; then
    sudo warp-cli --accept-tos disconnect || echo '::warning::Could not disconnect WARP.'
    sudo warp-cli --accept-tos registration delete || echo '::warning::Could not delete the WARP registration; check Zero Trust devices.'
  fi
  case "$RUNNER_OS" in
    Linux) sudo systemctl stop warp-svc || echo '::warning::Could not stop warp-svc.' ;;
    macOS)
      sudo launchctl bootout system/com.cloudflare.1dot1dot1dot1.macos.warp.daemon ||
        echo '::warning::Could not stop the WARP daemon.'
      ;;
  esac
  rm -f "$state/warp-managed"
fi
